const axios = require('axios');
const abiDecoder = require('abi-decoder');
require('dotenv').config();

const DATA = '';

const API_KEY = process.env.API_KEY;

const CONTRACT_ADDRESS = '0x68b3465833fb72A70ecDF485E0e4C7bD8665Fc45'; // Swap Router contract
const URL = `https://api.etherscan.io/api?module=contract&action=getabi&address=${CONTRACT_ADDRESS}&apikey=${API_KEY}`;

const getAbi = async () => {
  const res = await axios.get(URL);
  return JSON.parse(res.data.result);	
}

const main = async () => {
  const ABI = await getAbi();
  abiDecoder.addABI(ABI);
  const decodedData = abiDecoder.decodeMethod(DATA);
  const innerDecodedData = abiDecoder.decodeMethod(decodedData.params[1].value[0])
  console.log("innerDecodedData: ",innerDecodedData);
}

main();